#include <iostream>
#include <vector>
#include <algorithm>
#include <string>

using namespace std;

const int MAXN = 66;

int r, c, n;
string s;
long long comb[MAXN][MAXN];

int countA[MAXN], countB[MAXN];
vector<long long> partials[MAXN], partials_zero[MAXN];

void prepare_combinations() {
    for (int i = 0; i <= n; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
    }
}

long long calc_dif(int conf, int a_prev, int b_prev) {
    long long total = 0;
    for (int i = 0; i <= c; ++i) {
        if (conf & (1 << i)) {
            b_prev++;
            total -= comb[b_prev - 1][r - 1] * (comb[n - b_prev][r] - comb[a_prev][r]);
        } else {
            a_prev++;
            total += comb[a_prev - 1][r - 1] * (comb[n - a_prev][r] - comb[b_prev][r]);
        }
    }
    return total;
}

bool valid_conf(int conf) {
    for (int i = 0; i <= c; ++i) {
        if (s[2 * r + c + i] == 'A' && ((conf >> i) & 1) == 1) return false;
        if (s[2 * r + c + i] == 'B' && ((conf >> i) & 1) == 0) return false;
    }
    return true;
}

void process_second() {
    int total_conf = 1 << (c + 1);
    for (int conf = 0; conf < total_conf; ++conf) {
        int b_count = __builtin_popcount(conf);
        int a_count = c + 1 - b_count;
        if (valid_conf(conf))
            partials[a_count].push_back(calc_dif(conf, r + c - a_count, r + c - b_count));
        else
            partials_zero[a_count].push_back(calc_dif(conf, r + c - a_count, r + c - b_count));
    }
    for (int i = 0; i <= c + 1; ++i) {
        sort(partials[i].begin(), partials[i].end());
        sort(partials_zero[i].begin(), partials_zero[i].end());
    }
}

long long get_coef(int conf) {
    int i;
    for (i = 0; i <= c; ++i) {
        if ( ((conf >> i) & 1) != (conf & 1) ) break;
    }
    for (int j = i; j <= c; ++j) {
        if (s[2 * r - 1 + j] == 'A' && (((conf >> j) & 1) == 1)) return 0;
        if (s[2 * r - 1 + j] == 'B' && (((conf >> j) & 1) == 0)) return 0;
    }
    int setA = r - 1 + ((conf & 1) == 0 ? i : 0);
    int setB = r - 1 + ((conf & 1) == 1 ? i : 0);
    if (setA < countA[2 * r - 2 + i]) return 0;
    if (setB < countB[2 * r - 2 + i]) return 0;
    int total = setA + setB - countA[2 * r - 2 + i] - countB[2 * r - 2 + i];
    int choose = setA - countA[2 * r - 2 + i];
    return comb[total][choose];
}

void update_answer(pair<long long, long long>& ans, pair<long long, long long> act) {
    if (act.first < 0) act.first = -act.first;
    if (ans.first > act.first) {
        ans = act;
    } else if (ans.first == act.first) {
        ans.second += act.second;
    }
}

long long count_occurrences(const vector<long long>& data, long long val) {
    auto low = lower_bound(data.begin(), data.end(), val);
    auto up = upper_bound(data.begin(), data.end(), val);
    return up - low;
}

long long main_compute() {
    int total_conf = 1 << (c + 1);
    pair<long long, long long> answer = {1LL << 60, 0};
    for (int conf = 0; conf < total_conf; ++conf) {
        int b_count = __builtin_popcount(conf);
        int a_count = c + 1 - b_count;
        long long act = calc_dif(conf, r - 1, r - 1);
        long long coef = get_coef(conf);
        auto it = lower_bound(partials[c + 1 - a_count].begin(), partials[c + 1 - a_count].end(), -act);
        if (it != partials[c + 1 - a_count].end()) {
            if (answer.first >= abs(*it + act)) {
                long long count = count_occurrences(partials[c + 1 - a_count], *it);
                update_answer(answer, {abs(*it + act), coef * count});
            }
        }
        if (it != partials[c + 1 - a_count].begin()) {
            it--;
            if (answer.first >= abs(*it + act)) {
                long long count = count_occurrences(partials[c + 1 - a_count], *it);
                update_answer(answer, {abs(*it + act), coef * count});
            }
        }
        long long zero_coef = 0;
        auto it_zero = lower_bound(partials_zero[c + 1 - a_count].begin(), partials_zero[c + 1 - a_count].end(), -act);
        if (it_zero != partials_zero[c + 1 - a_count].end()) {
            long long count = count_occurrences(partials[c + 1 - a_count], *it_zero);
            if (answer.first >= abs(*it_zero + act))
                update_answer(answer, {abs(*it_zero + act), zero_coef * count});
        }
        if (it_zero != partials_zero[c + 1 - a_count].begin()) {
            it_zero--;
            long long count = count_occurrences(partials[c + 1 - a_count], *it_zero);
            if (answer.first >= abs(*it_zero + act))
                update_answer(answer, {abs(*it_zero + act), zero_coef * count});
        }
    }
    return answer.second;
}

int main() {
    cin >> r >> c >> s;
    n = 2 * (r + c);
    prepare_combinations();
    for (int i = 1; i <= n; ++i) {
        countA[i] = countA[i - 1] + (s[i - 1] == 'A' ? 1 : 0);
        countB[i] = countB[i - 1] + (s[i - 1] == 'B' ? 1 : 0);
    }
    process_second();
    cout << main_compute() << "\n";
    return 0;
}
